-- Deployment-safe OpenAI Luna job-requirement seed.
-- Coverage: 2,822 of the 2,833 Wanted job postings in
-- wanted_jobs_merge_20260804_normal.sql.
-- The remaining 11 IDs have no row in the source requirement dump; backfill
-- them from the crawler/AI only if requirement data is needed for them:
-- 312163, 326794, 326795, 339163, 339485, 362485, 364367, 370778,
-- 371383, 371991, 372177.
-- This intentionally does not import openai_luna_requirement_seed.sql,
-- a full local-DB dump containing skills, aliases, requirements, and
-- job-skill rows that reference local numeric job_posting IDs.
-- Prerequisites: Wanted job postings are imported and Flyway V10/V11 or newer has run.
-- This file does not insert skills or aliases with local numeric IDs.
SET NAMES utf8mb4;
START TRANSACTION;

CREATE TEMPORARY TABLE _luna_requirement_seed (
  external_job_id VARCHAR(255) NOT NULL,
  type VARCHAR(30) NOT NULL,
  content TEXT NOT NULL,
  source_excerpt TEXT NOT NULL,
  importance VARCHAR(30) NOT NULL,
  extraction_source VARCHAR(30) NOT NULL,
  verification_status VARCHAR(30) NOT NULL
);

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

;

SELECT jp.id, seed.type, seed.content, seed.source_excerpt, seed.importance, seed.extraction_source, seed.verification_status
FROM _luna_requirement_seed seed
JOIN job_postings jp ON jp.source_provider = 'WANTED' AND jp.external_job_id = seed.external_job_id
WHERE NOT EXISTS (SELECT 1 FROM job_requirements existing
  WHERE existing.job_posting_id = jp.id AND existing.type = seed.type
    AND existing.content = seed.content AND existing.importance = seed.importance
    AND existing.extraction_source = seed.extraction_source);

CREATE TEMPORARY TABLE _luna_job_skill_seed (
  external_job_id VARCHAR(255) NOT NULL,
  skill_name VARCHAR(100) NOT NULL,
  requirement_type VARCHAR(30) NOT NULL,
  source_excerpt TEXT NOT NULL
);

;

;

;

;

;

;

;

SELECT jp.id, skill.id, skill.id, seed.requirement_type, seed.source_excerpt
FROM _luna_job_skill_seed seed
JOIN job_postings jp ON jp.source_provider = 'WANTED' AND jp.external_job_id = seed.external_job_id
JOIN skills skill ON skill.name = seed.skill_name AND skill.catalog_status = 'CANONICAL'
ON DUPLICATE KEY UPDATE canonical_skill_id = VALUES(canonical_skill_id), source_excerpt = VALUES(source_excerpt);

SELECT COUNT(DISTINCT seed.external_job_id) AS missing_wanted_job_postings
FROM _luna_requirement_seed seed
LEFT JOIN job_postings jp ON jp.source_provider = 'WANTED' AND jp.external_job_id = seed.external_job_id
WHERE jp.id IS NULL;
DROP TEMPORARY TABLE _luna_job_skill_seed;
DROP TEMPORARY TABLE _luna_requirement_seed;
COMMIT;
